#!/usr/bin/env node
/**
 * generate-immersive-themes.mjs
 *
 * Emits theme/css/immersive-themes.css from the hand-maintained
 * ../immersive-themes.json, resolving each Family.step reference against the
 * raw ../tokens/colors.json export. The CSS is a generated file — edit the
 * JSON and re-run this script instead.
 *
 * Each theme becomes one `[data-immersive-theme="<name>"]` block of
 * `--immersive-*` custom properties, so a page switches theme by changing
 * that one attribute on its root.
 *
 * Usage: node theme/scripts/generate-immersive-themes.mjs
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const themeRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
export const JSON_FILE = join(themeRoot, "immersive-themes.json");
export const CSS_FILE = join(themeRoot, "css/immersive-themes.css");
export const STEPS = ["100", "75", "50", "25"];
/** Stepped color sets a theme may define; `support` is Ultra's second accent. */
export const SETS = ["palette", "accent", "support"];

export function loadImmersiveThemes() {
  return {
    ...JSON.parse(readFileSync(JSON_FILE, "utf8")),
    colors: JSON.parse(readFileSync(join(themeRoot, "tokens/colors.json"), "utf8")),
  };
}

/** "Light Grey.75" -> "#bccfd9"; throws on a reference the export lacks. */
export function resolveColor(colors, ref) {
  const dot = ref.lastIndexOf(".");
  const value = colors[ref.slice(0, dot)]?.[ref.slice(dot + 1)]?.value;
  if (!value) throw new Error(`Unknown color token: ${ref}`);
  return value;
}

const declare = (colors, vars) => vars.map(([key, ref]) => `  --immersive-${key}: ${resolveColor(colors, ref)}; /* ${ref} */`).join("\n");
const stepped = (prefix, set) => STEPS.flatMap((step) => [
  [`${prefix}-${step}`, set[step].bg],
  [`on-${prefix}-${step}`, set[step].fg],
]);

export function renderImmersiveCss({ secondary, themes, colors }) {
  const shared = `/* Secondary colours, available in every theme */\n[data-immersive-theme] {\n${
    declare(colors, Object.entries(secondary).flatMap(([family, set]) => stepped(family, set)))}\n}`;
  const blocks = Object.entries(themes).map(([name, theme]) => {
    const vars = [
      ["canvas", theme.canvas],
      ["text", theme.text],
      ...SETS.filter((set) => theme[set]).flatMap((set) => stepped(set, theme[set])),
      ["action", theme.action.bg],
      ["on-action", theme.action.fg],
    ];
    return `/* ${theme.label}: ${Object.entries(theme.ratio).map(([family, share]) => `${family} ${share}`).join(" / ")} */\n`
      + `[data-immersive-theme="${name}"] {\n${declare(colors, vars)}\n  background: var(--immersive-canvas);\n  color: var(--immersive-text);\n}`;
  });
  return `/* Generated by theme/scripts/generate-immersive-themes.mjs from theme/immersive-themes.json. Do not hand-edit. */\n\n${[shared, ...blocks].join("\n\n")}\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(CSS_FILE, renderImmersiveCss(loadImmersiveThemes()));
  console.log(`Wrote ${CSS_FILE}`);
}
